-- 刈寄線（tokyo-kariyose）の区間データ。tools/road.py build data/roads/tokyo-kariyose.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否と規制：東京都森林事務所「森林事務所管理林道の通行規制について」通行状況一覧（令和8年10月2日現在）。「通行規制」は林業関係者以外の車両の乗り入れを規制。data/sources/tokyo-forestry-2026-10-02.tsv

set search_path = public, extensions;

insert into administrators (name, kind) values ('東京都森林事務所 秋川林務出張所', '都')
on conflict (name) do nothing;
insert into roads (name, kind) values ('刈寄線', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '刈寄線');

-- あきる野市：特になし（約1.1km）
insert into segments (road_id, administrator_id, surface, difficulty, general_access, note, geom)
select r.id, a.id, null, null, '可', 'あきる野市：特になし',
  ST_SetSRID(ST_GeomFromGeoJSON('{"type":"LineString","coordinates":[[139.2008445,35.7060011],[139.2007424,35.7060561],[139.2006562,35.7060922],[139.2005107,35.7061129],[139.2003819,35.7061652],[139.2002931,35.7062145],[139.2002599,35.7062808],[139.200256,35.7063335],[139.2002587,35.7063879],[139.2003114,35.7063991],[139.2003436,35.7064383],[139.2003815,35.7065625],[139.2003996,35.7066568],[139.2004138,35.7067427],[139.2004219,35.7068833],[139.2004401,35.7070398],[139.2004695,35.7071705],[139.2005191,35.7072722],[139.2005793,35.7073604],[139.2006555,35.7074776],[139.2007316,35.7075892],[139.2007817,35.7077145],[139.2007803,35.7078164],[139.2008131,35.7078981],[139.2008663,35.7079719],[139.2009519,35.7080764],[139.2009897,35.7081497],[139.2010368,35.7083163],[139.2010914,35.7084231],[139.2011508,35.7085504],[139.2012772,35.708735],[139.2013576,35.7088516],[139.2014009,35.7089493],[139.2014221,35.7090298],[139.2014332,35.7091564],[139.2014261,35.7093931],[139.2014374,35.7095429],[139.2014775,35.709681],[139.2015343,35.7098233],[139.2018217,35.710363],[139.2019469,35.7105596],[139.2020639,35.7106895],[139.2021806,35.7108694],[139.202298,35.711061],[139.2024044,35.7112779],[139.2024488,35.7114456],[139.2025121,35.7117256],[139.2025349,35.7118764],[139.2025588,35.7119395],[139.2026071,35.712019],[139.2027943,35.7123099],[139.2028412,35.7124211],[139.202865,35.712522],[139.202864,35.712643],[139.2028555,35.7127768],[139.202753,35.7131606],[139.2026949,35.7135457],[139.2026605,35.7141779],[139.2026803,35.7142945],[139.2027172,35.7143853],[139.2027836,35.7144759],[139.2028675,35.7145723],[139.2029857,35.7146813],[139.2030507,35.7147516],[139.2030839,35.7148211]]}'), 4326)
from roads r, administrators a
where r.name = '刈寄線' and a.name = '東京都森林事務所 秋川林務出張所';

-- 確認：この林道の区間と規制の数
select s.note as 区間, count(x.id) as 規制数
from segments s join roads r on r.id = s.road_id left join restrictions x on x.segment_id = s.id
where r.name = '刈寄線' group by s.id, s.note order by s.id;
